static readonly string[] Keys = { "PROTOCOL",  "FRAMES",      "WINDOW",      "SEQBITS",
                                  "TIMEOUT",   "DELAY",       "INTERVAL",    "MAXTICKS",
                                  "DUPACK",    "NAK",         "BACKOFF",     "CONGESTION",
                                  "UNSAFE",    "TRACE",       "RANDOM",      "LOSEDATA",
                                  "LOSECTRL",  "CORRUPTDATA", "CORRUPTCTRL", "DELAYDATA",
                                  "DELAYCTRL", "SNAPSHOT" };
        string key = line[0];
        int index = Array.IndexOf(Keys, key), count = line.Length - 1;
        if (index < 0)
            return "unknown key " + key;
        if (values.ContainsKey(key))
            return "duplicate key " + key;
        if (key == "RANDOM" ? count != 3 : index >= 15 ? count < 1 : count != 1)
            return "wrong number of values for " + key;
        values[key] = line.Skip(1).ToArray();
        } else if (index >= 15) {
            HashSet<int> seen = new();
            foreach (string value in v) {
                string[] parts = value.Split(':');
                int number = int.Parse(parts[0]);
                int lower = key == "SNAPSHOT" ? 0 : 1, upper = key == "SNAPSHOT" ? 2000 : 9999;
                if (number < lower || number > upper || !seen.Add(number))
                    valid = false;
                if (index == 19 || index == 20) {
                    int extra = int.Parse(parts[1]);
                    if (extra < 1 || extra > 50)
                        valid = false;
                }
            }
        if (!valid)
            return "bad value for " + key;
        string error = Validate(config, lines);
        if (error != null) {
            Output.Add("error: " + error);
            results.Add(new Result(config, "invalid"));
        } else
            results.Add(new Simulation(config).Run());
